{ action_raise_error("UNLOAD_FILAMENT: DISTANCE=%.1f is longer than max_extrude_only_distance (%.1f)" % (DISTANCE, MAX_E)) }
{% endif %}

{% set verbose = printer["gcode_macro _USER_VARIABLES"].verbose %}
