_BUFFER_HALT
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_heater_off VALUE=0
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=1

{% if filament_sensor_enabled %}
_KLIPPAIN_DISABLE_FILAMENT_SENSORS
