{% set chamber_sensor_name = printer["gcode_macro _USER_VARIABLES"].chamber_temperature_sensor_name %}
{% set chamber_sensor_type = printer["gcode_macro _USER_VARIABLES"].chamber_temperature_sensor_type|default("temperature_sensor") %}
