gcode_macro _BUFFER_CHECK.gcode:
{% set mode = params.MODE|default("info")|string %}
{% set bname = printer["gcode_macro _BUFFER_VARS"].buffer_sensor %}
{% set have_bsensor = bname != "" and ("filament_switch_sensor " ~ bname|lower) in printer.configfile.settings %}
{% if have_bsensor %}
{% set detected = printer["filament_switch_sensor " ~ bname].filament_detected %}
{% if mode == "unload" %}
{% if detected %}
RESPOND MSG="Buffer: filament still in the buffer - pull it out by hand to swap the spool"
{% else %}
RESPOND MSG="Buffer: inlet clear, filament is out"
{% endif %}
{% elif mode == "load" %}
{% if detected %}
RESPOND MSG="Buffer: filament present at the inlet, feeding"
{% else %}
RESPOND MSG="Buffer: WARNING - no filament at the buffer inlet, the feed will do nothing"
{% endif %}
{% else %}
RESPOND MSG="Buffer inlet: {'filament detected' if detected else 'no filament'}"
{% endif %}
{% elif mode == "info" %}
RESPOND MSG="Buffer: no inlet sensor configured (see variable_buffer_sensor in _BUFFER_VARS)"
{% endif %}

gcode_macro _OSS_CHECK.gcode:
{% set mode = params.MODE|default("info")|string %}
{% set oname = printer["gcode_macro _BUFFER_VARS"].oss_sensor %}
{% set have_oss = oname != "" and ("filament_switch_sensor " ~ oname|lower) in printer.configfile.settings %}
{% if have_oss %}
{% set detected = printer["filament_switch_sensor " ~ oname].filament_detected %}
{% if mode == "unload" %}
{% if detected %}
RESPOND TYPE=error MSG="OSS: WARNING - filament still at the extruder inlet, the unload may have failed"
{% else %}
RESPOND MSG="OSS: extruder clear"
{% endif %}
{% elif mode == "load" %}
{% if detected %}
RESPOND MSG="OSS: filament loaded"
{% else %}
RESPOND TYPE=error MSG="OSS: WARNING - no filament at the extruder inlet after loading"
{% endif %}
{% else %}
RESPOND MSG="OSS: {'filament detected' if detected else 'no filament'}"
{% endif %}
{% elif mode == "info" %}
RESPOND MSG="OSS: no sensor configured (see variable_oss_sensor in _BUFFER_VARS)"
{% endif %}

