{% endif %}

{% if HEATER_OFF %}
M104 S0
RESPOND MSG="Filament: hotend turned off again (it was off before the auto load)"
{% endif %}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_heater_off VALUE=0
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=0
