gcode_macro load_filament.gcode:
{% set TEMP = params.TEMP|default(printer["gcode_macro _USER_VARIABLES"].print_default_extruder_temp)|float %}
{% set DISTANCE = params.DISTANCE|default(105)|float %}
{% set HEATER_OFF = params.HEATER_OFF|default(0)|int %}
{% set MAX_E = printer.configfile.settings.extruder.max_extrude_only_distance|float %}
{% set MIN_EXTRUDE_TEMP = printer.configfile.settings.extruder.min_extrude_temp|float %}
{% if DISTANCE > MAX_E %}
{ action_raise_error("LOAD_FILAMENT: DISTANCE=%.1f is longer than max_extrude_only_distance (%.1f)" % (DISTANCE, MAX_E)) }
{% endif %}

{% set cfg = printer["gcode_macro _BUFFER_VARS"] %}
{% set st = printer["gcode_macro _OSS_STATE"] %}
{% set buffer_enabled = cfg.buffer_enabled|int %}
{% set BUFFER_FEED_TIME = params.BUFFER_FEED_TIME|default(cfg.feed_time)|int %}

{% set oobj = "filament_switch_sensor " ~ cfg.oss_sensor %}
{% set have_oss = cfg.oss_sensor != "" and (oobj|lower) in printer.configfile.settings %}
{% set oss_ready = have_oss and printer[oobj].enabled %}
{% set oss_sees_filament = have_oss and printer[oobj].filament_detected %}

{% set bobj = "filament_switch_sensor " ~ cfg.buffer_sensor %}
{% set have_bsensor = cfg.buffer_sensor != "" and (bobj|lower) in printer.configfile.settings %}
{% set buffer_empty = have_bsensor and not printer[bobj].filament_detected %}

{% if st.busy|int %}
RESPOND MSG="Filament: a load/unload is already running (BUFFER_STOP cancels it)"

{% elif oss_sees_filament or not buffer_enabled %}

_LOAD_FILAMENT_EXTRUDE TEMP={TEMP} DISTANCE={DISTANCE} HEATER_OFF={HEATER_OFF}

{% elif oss_ready %}
{% if buffer_empty %}
RESPOND TYPE=error MSG="Buffer: no filament at the buffer inlet - push the new filament into the buffer first"
{% else %}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_temp VALUE={TEMP}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_distance VALUE={DISTANCE}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_heater_off VALUE={HEATER_OFF}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_pending VALUE=1
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=1
{% if printer.extruder.target < MIN_EXTRUDE_TEMP %}
M104 S{TEMP}
{% endif %}
BUFFER_FEED
UPDATE_DELAYED_GCODE ID=_buffer_load_timeout DURATION={cfg.load_timeout|int}
RESPOND MSG="Buffer: feeding until the OSS sees filament - wait for 'OSS: filament loaded' before RESUME"
{% endif %}

{% else %}

_BUFFER_CHECK MODE=load
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=1
{% if printer.extruder.target < MIN_EXTRUDE_TEMP %}
M104 S{TEMP}
{% endif %}
BUFFER_FEED
G4 P{BUFFER_FEED_TIME}
_BUFFER_HALT
_LOAD_FILAMENT_EXTRUDE TEMP={TEMP} DISTANCE={DISTANCE} HEATER_OFF={HEATER_OFF}
{% endif %}

