gcode_macro _load_filament_extrude.gcode:
{% set TEMP = params.TEMP|default(printer["gcode_macro _USER_VARIABLES"].print_default_extruder_temp)|float %}
{% set DISTANCE = params.DISTANCE|default(105)|float %}
{% set HEATER_OFF = params.HEATER_OFF|default(0)|int %}

{% set verbose = printer["gcode_macro _USER_VARIABLES"].verbose %}
{% set filament_sensor_enabled = printer["gcode_macro _USER_VARIABLES"].filament_sensor_enabled|default(False) %}
{% set klippain_mmu_enabled = printer["gcode_macro _USER_VARIABLES"].klippain_mmu_enabled|default(False) %}

_BUFFER_HALT
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=1

{% if filament_sensor_enabled %}
_KLIPPAIN_DISABLE_FILAMENT_SENSORS
{% if verbose %}
RESPOND MSG="Filament sensors deactivated to load filament"
{% endif %}
{% endif %}

{% if klippain_mmu_enabled %}
{% set was_clog_detection = printer.mmu.clog_detection %}
_KLIPPAIN_MMU_SET_CLOGDETECTION STATE=0
{% endif %}

SAVE_GCODE_STATE NAME=LOAD_FILAMENT_state
_LOW_TEMP_CHECK T={TEMP}
M83
G92 E0
G1 E{DISTANCE} F200
G1 E50 F150


M400

G92 E0
RESTORE_GCODE_STATE NAME=LOAD_FILAMENT_state

{% if filament_sensor_enabled %}
_KLIPPAIN_ENABLE_FILAMENT_SENSORS
{% if verbose %}
RESPOND MSG="Filament loaded, filament sensors reactivated"
{% endif %}
{% endif %}

{% if klippain_mmu_enabled %}
_KLIPPAIN_MMU_SET_CLOGDETECTION STATE={was_clog_detection}
{% endif %}

{% if HEATER_OFF %}
M104 S0
RESPOND MSG="Filament: hotend turned off again (it was off before the auto load)"
{% endif %}
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=load_heater_off VALUE=0
SET_GCODE_VARIABLE MACRO=_OSS_STATE VARIABLE=busy VALUE=0
_OSS_CHECK MODE=load
